//! Android service owns the runtime independently of any Activity/WebView.
use std::{path::PathBuf,sync::{Arc,Mutex,OnceLock}};
use delta_host_runtime::{HostRuntime,ProfileCodec};use jni::{JNIEnv,JavaVM,objects::{GlobalRef,JObject,JString,JValue,JByteArray}};use serde_json::Value;
struct Java {vm:JavaVM,context:GlobalRef,crypto:GlobalRef,controls:GlobalRef}
impl Java {
 fn init(env:&mut JNIEnv,context:JObject)->Result<Self,String>{
  let vm=env.get_java_vm().map_err(|_|"jvm")?;let loader=env.call_method(&context,"getClassLoader","()Ljava/lang/ClassLoader;",&[]).and_then(|v|v.l()).map_err(|_|"loader")?;
  let mut class=|name:&str|->Result<GlobalRef,String>{let s=env.new_string(name).map_err(|_|"class")?;let v=env.call_method(&loader,"loadClass","(Ljava/lang/String;)Ljava/lang/Class;",&[JValue::Object(s.as_ref())]).and_then(|v|v.l()).map_err(|_|"class")?;env.new_global_ref(v).map_err(|_|"class".into())};
  let crypto=class("dev.delta.android.platform.ProfileCrypto")?;let controls=class("dev.delta.android.platform.PlatformControls")?;let context=env.new_global_ref(context).map_err(|_|"context")?;Ok(Self{vm,context,crypto,controls})
 }
 fn crypto(&self,operation:&str,bytes:&[u8])->std::io::Result<Vec<u8>>{let result=(||->jni::errors::Result<Vec<u8>>{let mut env=self.vm.attach_current_thread()?;let op=env.new_string(operation)?;let data=env.byte_array_from_slice(bytes)?;let out=env.call_static_method(&self.crypto,"transform","(Ljava/lang/String;[B)[B",&[JValue::Object(op.as_ref()),JValue::Object(data.as_ref())])?.l()?;env.convert_byte_array(JByteArray::from(out))})();result.map_err(|_|{if let Ok(mut env)=self.vm.attach_current_thread(){let _=env.exception_clear();}std::io::Error::other("Android Keystore unavailable")})}
 fn platform(&self,method:&str,args:&Value)->Result<Value,String>{let mut env=self.vm.attach_current_thread().map_err(|_|"jvm")?;let m=env.new_string(method).map_err(|_|"input")?;let a=env.new_string(args.to_string()).map_err(|_|"input")?;let result=env.call_static_method(&self.controls,"dispatch","(Landroid/content/Context;Ljava/lang/String;Ljava/lang/String;)Ljava/lang/String;",&[JValue::Object(self.context.as_obj()),JValue::Object(m.as_ref()),JValue::Object(a.as_ref())]);let value=match result{Ok(v)=>v.l().map_err(|_|"result")?,Err(_)=>{let _=env.exception_clear();return Err("platform_operation_failed".into())}};let s:JString=value.into();let text:String=env.get_string(&s).map_err(|_|"result")?.into();serde_json::from_str(&text).map_err(|_|"invalid_platform_result".into())}
}
struct Codec(Arc<Java>);impl ProfileCodec for Codec{fn seal(&self,b:&[u8])->std::io::Result<Vec<u8>>{self.0.crypto("seal",b)}fn open(&self,b:&[u8])->std::io::Result<Vec<u8>>{self.0.crypto("open",b)}}
struct Mobile {rt:tokio::runtime::Runtime,node:Mutex<Option<Arc<HostRuntime>>>,java:Arc<Java>}
static MOBILE:OnceLock<Mobile>=OnceLock::new();static INIT:Mutex<()>=Mutex::new(());
pub fn start(env:&mut JNIEnv,context:JObject,home:PathBuf)->Result<(),String>{let _guard=INIT.lock().map_err(|_|"runtime_lock")?;
 if MOBILE.get().is_none(){let java=Arc::new(Java::init(env,context)?);let rt=tokio::runtime::Runtime::new().map_err(|_|"runtime")?;MOBILE.set(Mobile{rt,node:Mutex::new(None),java}).map_err(|_|"runtime")?;}
 let m=MOBILE.get().unwrap();let mut slot=m.node.lock().map_err(|_|"runtime_lock")?;if slot.is_none(){let node=m.rt.block_on(HostRuntime::open_with_codec(home,"android",Some(Arc::new(Codec(m.java.clone()))))).map_err(|e|e.code)?;*slot=Some(Arc::new(node));}Ok(())
}
pub fn active()->Result<Arc<HostRuntime>,String>{MOBILE.get().ok_or("runtime_not_started")?.node.lock().map_err(|_|"runtime_lock")?.clone().ok_or("node_stopped".into())}
pub fn stop(){if let Some(m)=MOBILE.get(){if let Ok(mut slot)=m.node.lock(){if let Some(node)=slot.take(){m.rt.block_on(node.stop())}}}}
pub fn platform(method:&str,args:&Value)->Result<Value,String>{MOBILE.get().ok_or("runtime_not_started")?.java.platform(method,args)}
pub fn poll()->Value{let Some(m)=MOBILE.get()else{return serde_json::json!([])};let Ok(node)=active()else{return serde_json::json!([])};m.rt.block_on(async{
 let call=|cap:&str,args:Value,target:Option<String>|{let node=node.clone();let cap=cap.to_string();async move{node.call(serde_json::json!({"capability":cap,"args":args,"node":target})).await}};
 let preferences=call("host.document_list",serde_json::json!({"namespace":"preferences"}),None).await.unwrap_or(serde_json::json!([]));let stored=preferences.as_array().into_iter().flatten().find(|v|v["id"]=="os-notified").and_then(|v|v["keys"].as_array()).cloned().unwrap_or_default();let local=call("core.info",serde_json::json!({}),None).await.unwrap_or_default();let local_id=local["node_id"].as_str().unwrap_or("local");let mut nodes=vec![None];let peers=call("peers.list",serde_json::json!({}),None).await.unwrap_or(serde_json::json!([]));for p in peers.as_array().into_iter().flatten().take(32){if p["online"]==true{if let Some(id)=p["node_id"].as_str(){nodes.push(Some(id.to_owned()))}}}
 let mut out=vec![];for target in nodes{let cs=call("core.components",serde_json::json!({}),target.clone()).await.unwrap_or(serde_json::json!([]));for p in cs.as_array().into_iter().flatten(){let Some(id)=p["id"].as_str()else{continue};let Some(cap)=p["metadata"]["ui"]["endpoints"]["notifications"].as_str()else{continue};if !cap.starts_with(&format!("{id}.")){continue}let rows=call(cap,serde_json::json!({}),target.clone()).await.unwrap_or(serde_json::json!([]));for n in rows.as_array().into_iter().flatten().take(100){let (Some(post),Some(title))=(n["id"].as_str(),n["title"].as_str())else{continue};if post.len()>256{continue}let key=format!("plugin:{}:{}:{post}",p["metadata"]["ui"]["id"].as_str().unwrap_or(id),target.as_deref().unwrap_or(local_id));if stored.iter().any(|s|s.as_str()==Some(key.as_str())){continue}out.push(serde_json::json!({"id":key,"title":title.chars().take(200).collect::<String>(),"body":n["body"].as_str().unwrap_or("").chars().take(2000).collect::<String>(),"route":format!("/plugins/{}",p["metadata"]["ui"]["id"].as_str().unwrap_or(id))}));if out.len()>=10{return serde_json::json!(out)}}}}serde_json::json!(out)
})}
pub fn acknowledge(keys:&str){let Some(m)=MOBILE.get()else{return};let Ok(node)=active()else{return};let Ok(keys)=serde_json::from_str::<Vec<String>>(keys)else{return};m.rt.block_on(async{let docs=node.call(serde_json::json!({"capability":"host.document_list","args":{"namespace":"preferences"}})).await.unwrap_or(serde_json::json!([]));let mut all:Vec<Value>=docs.as_array().into_iter().flatten().find(|d|d["id"]=="os-notified").and_then(|d|d["keys"].as_array()).cloned().unwrap_or_default();for id in keys.into_iter().take(10){if id.len()<=512&&!all.iter().any(|v|v.as_str()==Some(&id)){all.push(Value::String(id))}}while all.len()>500||serde_json::to_vec(&all).map(|b|b.len()>50000).unwrap_or(true){if all.is_empty(){break}all.remove(0);}let _=node.call(serde_json::json!({"capability":"host.document_put","args":{"namespace":"preferences","key":"os-notified","value":{"id":"os-notified","keys":all}}})).await;})}
